def f(s, t, n):
	if s[0] != t[0] or s[n - 1] != t[n - 1]:
		return -1
	(i, j, edits) = (0, 0, 0)
	while True:
		while i < n - 1 and s[i] == s[i + 1]:
			i += 1
		while j < n - 1 and t[j] == t[j + 1]:
			j += 1
		if i < n - 1 and j < n - 1:
			edits += abs(i - j)
		elif i == n - 1 and j == n - 1:
			return edits + abs(i - j)
		else:
			return -1
		i += 1
		j += 1
T = int(input())
while T:
	n = int(input())
	(s, t) = (input(), input())
	print(f(s, t, n))
	T -= 1
